/**
 * CTrain (requirement.md §7.9): line colours and the line data shared with the World Map.
 * supabase/data/calgary_ctrain.json is generated by build_ctrain.py from OpenStreetMap (ODbL).
 */
import raw from '../../../../../supabase/data/calgary_ctrain.json';

export interface CtrainLine {
  line: string;
  colour: string;
  /** Track centreline, [lon, lat] points. */
  track: [number, number][];
  /** Station names in stop order. */
  stations: string[];
}

export interface CtrainData {
  lines: CtrainLine[];
  /** Station name → [lon, lat]. */
  stations: Record<string, [number, number]>;
}

const isPoint = (v: unknown): v is [number, number] => Array.isArray(v) && v.length === 2 && v.every((n) => typeof n === 'number');

/** Validates the generated file; throws listing every problem. */
export function decodeCtrain(data: unknown): CtrainData {
  const errors: string[] = [];
  const d = data as { lines?: unknown; stations?: unknown };
  const stations: Record<string, [number, number]> = {};
  for (const [k, v] of Object.entries((d?.stations ?? {}) as Record<string, unknown>)) {
    if (isPoint(v)) stations[k] = v;
    else errors.push(`station ${k}`);
  }
  const lines: CtrainLine[] = [];
  for (const l of (Array.isArray(d?.lines) ? d.lines : []) as Record<string, unknown>[]) {
    const track = l?.track;
    const names = l?.stations;
    if (typeof l?.line !== 'string' || typeof l?.colour !== 'string' || !Array.isArray(track) || !track.every(isPoint) || !Array.isArray(names)) {
      errors.push(`line ${String(l?.line)}`);
      continue;
    }
    for (const n of names) if (!stations[n as string]) errors.push(`line ${l.line}: unknown station ${String(n)}`);
    lines.push({ line: l.line, colour: l.colour, track, stations: names as string[] });
  }
  if (lines.length === 0) errors.push('no lines');
  if (errors.length > 0) throw new Error(`Invalid CTrain data: ${errors.join('; ')}`);
  return { lines, stations };
}

export const CTRAIN: CtrainData = decodeCtrain(raw);

const COLOURS: Record<string, string> = Object.fromEntries(CTRAIN.lines.map((l) => [l.line, l.colour]));

/** Line colour for a line name ("Red", "Blue"); grey for unknown lines. */
export const lineColour = (line: string): string => COLOURS[line] ?? '#8a8f99';
